class Clipboard{static async CanRead(){const t=await navigator.permissions.query({name:"clipboard-read"});return"granted"===t.state||"prompt"===t.state}static async CanWrite(){try{const t=await navigator.permissions.query({name:"clipboard-write"});return"granted"===t.state||"prompt"===t.state}catch{return!!navigator.clipboard}}static ReadText=()=>navigator.clipboard.readText();static WriteText=t=>navigator.clipboard.writeText(t);static async ReadImage(){const t=await navigator.clipboard.read();for(const a of t)for(const t of["image/png","image/jpeg","image/gif","image/webp"])if(a.types.includes(t))return await a.getType(t);return null}static WriteImage=async t=>{const a=new ClipboardItem({[t.type]:t});return navigator.clipboard.write([a])};static WriteMultiple=async(t,a)=>{const e=new Blob([t],{type:"text/plain"}),i=new ClipboardItem({"text/plain":e,[a.type]:a});return navigator.clipboard.write([i])}}window.GizmoWebJSInterop=window.GizmoWebJSInterop||{},window.GizmoWebJSInterop.Clipboard=Clipboard;